"""JSONRPC message definitions."""

import dataclasses
import json
import struct
import typing

from pydantic import ValidationError, validator

from jsilib import _utils
from jsilib.aio import helpers
from jsilib.jsi.interface import IJSIMessage
from jsilib.jsi.messages import JSIBytesMessage, JSIConcatenatedMessage, JSIStreamMessage

from . import _compat, exc

__all__ = export = _utils.ExportList(['SID', 'ID'])

_JSONRPC_VERSION = '2.1'

ID = typing.Union[int, str]
SID = typing.Union[int, str]
T = typing.TypeVar('T')


def _parse_pydantic_errors(errors: typing.List[dict]) -> typing.Dict[str, str]:
    result = {}
    for error in errors:
        result['.'.join(error['loc'])] = error['msg']
    return result


def _validate_jsonrpc(value):
    if value != _JSONRPC_VERSION:
        raise ValueError(f'expected {_JSONRPC_VERSION}, got {value}')
    return value


@export
@dataclasses.dataclass
class JSONRPCMessage(typing.Generic[T]):
    """A generic message class that glues together JSONRPC header part of type
    T with an optional binary payload."""
    head: T
    body: typing.Optional[IJSIMessage] = None

    _header_fmt = struct.Struct('!L')

    def dump(self) -> IJSIMessage:
        """Dump this message into an instance of :class:`IPayload` class."""
        head = json.dumps(self.head.to_dict()).encode('utf-8')
        payload = self._header_fmt.pack(len(head))
        payload += head
        if self.body is None:
            return JSIBytesMessage(payload)
        return JSIConcatenatedMessage([JSIBytesMessage(payload), self.body])

    @classmethod
    async def load(cls, payload: IJSIMessage) -> 'JSONRPCMessage[T]':
        """Load a new instance of :class:`Message` from given :class:`IPayload`
        object."""

        def is_request(head):
            return 'method' in head and\
                'id' in head

        def is_notification(head):
            return 'method' in head

        def is_response(head):
            return 'id' in head and\
                ('result' in head or 'error' in head)

        head_size, = cls._header_fmt.unpack(await helpers.read_all(payload, cls._header_fmt.size))
        raw_head = await helpers.read_all(payload, head_size)
        try:
            head = json.loads(raw_head)
        except json.decoder.JSONDecodeError:
            raise exc.MessageParsingError(f'Not a valid JSON object: {raw_head!r}')
        body = JSIStreamMessage(payload, payload.bytes_left())
        if is_request(head):
            return cls(JSONRPCRequest.from_dict(head), body=body)
        if is_notification(head):
            return cls(JSONRPCNotif.from_dict(head), body=body)
        if is_response(head):
            return cls(JSONRPCResponse.from_dict(head), body=body)
        raise exc.MessageValidationError(f'Unsupported or invalid JSONRPC object: {head!r}')


@export
class JSONRPCError(_compat.BaseDictableModel):
    """Represents error details of a failed response message."""
    code: int
    message: str
    data: typing.Optional[typing.Any]

    class Config:
        validate_assignment = True

    def to_dict(self) -> dict:
        return self.dict(exclude_none=True)

    @classmethod
    def from_dict(cls, data: dict) -> 'JSONRPCError':
        return cls(**data)

    @classmethod
    def parse_error(cls, data: typing.Any = None):
        return cls(code=-32700, message='Parse error', data=data)

    @classmethod
    def invalid_request(cls, data: typing.Any = None):
        return cls(code=-32600, message='Invalid Request', data=data)

    @classmethod
    def method_not_found(cls, data: typing.Any = None):
        return cls(code=-32601, message='Method not found', data=data)

    @classmethod
    def invalid_params(cls, data: typing.Any = None):
        return cls(code=-32602, message='Invalid params', data=data)

    @classmethod
    def internal_error(cls, data: typing.Any = None):
        return cls(code=-32603, message='Internal error', data=data)


@export
class JSONRPCRequest(_compat.BaseDictableModel):
    """Represents head part of a request message."""
    id: ID
    method: str
    jsonrpc: str = _JSONRPC_VERSION
    params: typing.Optional[typing.Any]
    sid: typing.Optional[SID]

    class Config:
        validate_assignment = True
        smart_union = True

    @validator('jsonrpc')
    def _validate_jsonrpc(cls, value):
        return _validate_jsonrpc(value)

    def to_dict(self) -> dict:
        return self.dict(exclude_none=True)

    @classmethod
    def from_dict(cls, data: dict) -> 'JSONRPCRequest':
        try:
            return cls(**data)
        except ValidationError as e:
            raise exc.MessageValidationError('Not a valid JSONRPC request', errors=_parse_pydantic_errors(e.errors()))


@export
class JSONRPCResponse(_compat.BaseDictableModel):
    """Represents head part of a response message."""
    id: ID
    jsonrpc: str = _JSONRPC_VERSION
    result: typing.Optional[typing.Any]
    error: typing.Optional[JSONRPCError]
    sid: typing.Optional[SID]

    class Config:
        validate_assignment = True
        smart_union = True

    @validator('jsonrpc')
    def _validate_jsonrpc(cls, value):
        return _validate_jsonrpc(value)

    @validator('result')
    def _validate_result(cls, value, values):
        if 'error' in values:
            raise ValueError("cannot set both 'error' and 'result'")
        return value

    @validator('error')
    def _validate_error(cls, value, values):
        if values.get('result') is not None:
            raise ValueError("cannot set both 'error' and 'result'")
        return value

    def to_dict(self) -> dict:
        d = self.dict(exclude_none=True)
        if 'error' not in d and 'result' not in d:
            d['result'] = None
        return d

    def is_success(self) -> bool:
        return self.error is None

    def is_error(self) -> bool:
        return self.error is not None

    @classmethod
    def from_dict(cls, data: dict) -> 'JSONRPCResponse':
        try:
            return cls(**data)
        except ValidationError as e:
            raise exc.MessageValidationError('Not a valid JSONRPC response', errors=_parse_pydantic_errors(e.errors()))

    @classmethod
    def from_request(
        cls, request: JSONRPCRequest, result: typing.Any = None, error: JSONRPCError = None
    ) -> 'JSONRPCResponse':
        """Create response object for given request object."""
        if error is not None:
            return cls(id=request.id, error=error, sid=request.sid)
        return cls(id=request.id, result=result, sid=request.sid)


@export
class JSONRPCNotif(_compat.BaseDictableModel):
    """Represents head part of a notification message."""
    method: str
    jsonrpc: str = _JSONRPC_VERSION
    params: typing.Optional[typing.Any]
    sid: typing.Optional[SID]

    class Config:
        validate_assignment = True
        smart_union = True

    @validator('jsonrpc')
    def _validate_jsonrpc(cls, value):
        return _validate_jsonrpc(value)

    def to_dict(self) -> dict:
        return self.dict(exclude_none=True)

    @classmethod
    def from_dict(cls, data: dict) -> 'JSONRPCNotif':
        try:
            return cls(**data)
        except ValidationError as e:
            raise exc.MessageValidationError(
                'Not a valid JSONRPC notification', errors=_parse_pydantic_errors(e.errors())
            )
